from vitrina import settings


HAS_DATA = "HAS_DATA"
STATUS = "STATUS"
OPENED = "OPENED"


def update_dataset_service_statuses(apps, schema_editor):
    Dataset = apps.get_model("vitrina_datasets", "Dataset")
    Comment = apps.get_model("vitrina_comments", "Comment")
    ContentType = apps.get_model('contenttypes', 'ContentType')
    User = apps.get_model('vitrina_users', 'User')

    sys_user, _ = User.objects.get_or_create(email=settings.SYSTEM_USER_EMAIL)

    for dataset in Dataset.objects.filter(
        is_public=True,
        service=True,
        endpoint_url__isnull=False
    ).exclude(
        status=HAS_DATA
    ):
        dataset.status = HAS_DATA
        dataset.save(update_fields=["status"])

        latest_status_comment = Comment.objects.filter(
            content_type=ContentType.objects.get_for_model(Dataset),
            object_id=dataset.pk,
            type=STATUS,
            status__isnull=False
        ).order_by('-created').first()

        if not latest_status_comment or latest_status_comment.status != OPENED:
            Comment.objects.create(
                content_type=ContentType.objects.get_for_model(dataset),
                object_id=dataset.pk,
                user=sys_user,
                type=STATUS,
                status=OPENED,
            )


